int get_bitmap_file(struct mddev *mddev, void __user *arg)
{
    struct bitmap_file *bf;
    int err;

    bf = kmalloc(sizeof(*bf), GFP_NOIO);
    if (!bf)
        return -ENOMEM;

    if (!mddev->bitmap)
        bf->pathname[0] = '\0';
    else {
        char *path;

        path = bdevname(mddev->bitmap->file->bdev, NULL);
        if (!path) {
            err = -ENOMEM;
            goto out;
