}

int get_bitmap_file(struct mddev *mddev, void __user *arg)
{
    struct bitmap_file *bf;
    int ret = 0;
    char *pathname;

    bf = kmalloc(sizeof(*bf), GFP_KERNEL);
    if (!bf)
        return -ENOMEM;

    if (!mddev->bitmap) {
        pathname = "";
    } else {
        pathname = mddev->bitmap->file;
        if (!pathname) {
            kfree(bf);
            return -EINVAL;
        }
    }

    if (copy_to_user(arg, bf, sizeof(*bf))) {
        ret = -EFAULT;
        goto out;
    }

out:
    kfree(bf);
    return ret;
}

int get_bitmap_file(struct mddev *mddev, void __user *arg)
{
    struct bitmap_file *bf;
    int ret = 0;

    bf = kmalloc(sizeof(*bf), GFP_KERNEL);
    if (!bf)
        return -ENOMEM;

    if (!mddev->bitmap) {
        bf->pathname[0] = '\0';
    } else {
        const char *path = mddev->bitmap->filename;
        if (strlen(path) >= BITMAP_FILE_LEN) {
            ret = -ENAMETOOLONG;
            goto out;
        }
        strcpy(bf->pathname, path);
    }

    if (copy_to_user(arg, bf, sizeof(*bf))) {
        ret = -EFAULT;
        goto out;
    }

out:
    kfree(bf);
    return ret;
}

